(function(root){const B=typeof module!=='undefined'?require('./battle-engine.js'):root.BattleRules;
const roster=[1,2,0,6,7,8],positions=[{r:7,c:3},{r:5,c:2},{r:6,c:1},{r:1,c:4},{r:2,c:3},{r:0,c:5},{r:6,c:4},{r:7,c:5},{r:6,c:2},{r:1,c:1},{r:2,c:1},{r:0,c:2}];
function arrange(p,selected){const out=p.map(v=>({...v})),taken=new Set([3,4,5,9,10,11].map(id=>out[id].r+','+out[id].c));for(const id of selected){let v=out[id],key=v.r+','+v.c;if(taken.has(key)){const free=[];for(let r=4;r<8;r++)for(let c=0;c<7;c++)if(!taken.has(r+','+c))free.push({r,c});free.sort((a,b)=>Math.abs(a.r-v.r)+Math.abs(a.c-v.c)-Math.abs(b.r-v.r)-Math.abs(b.c-v.c));out[id]=free[0];key=out[id].r+','+out[id].c}taken.add(key)}return out}
function create(p=positions,selected=[1,0,6,7,8]){if(!selected.length||selected.length>5||new Set(selected).size!==selected.length||selected.some(id=>!roster.includes(id)))throw Error('Invalid party');p=arrange(p,selected);const b=B.create(p,[{type:'sword',variant:'flame'},{type:'archer',variant:'alchemist'},{type:'mage',variant:'saint'}],[{type:'archer'},{type:'sword'},{type:'mage'}]);b.sideEngagement=true;b.blockEnemyUltimates=true;let enemy=0;for(const u of b.units){if(u.team===0){u.deployed=selected.includes(u.id);if(!u.deployed)u.hp=0}else{u.enemyArt=enemy++%3;u.hp=u.max=u.max*5;u.dmg=Math.max(1,Math.round(u.dmg*.2))}}return b}
const api={create,positions,roster,arrange};if(typeof module!=='undefined')module.exports=api;else root.TestEncounter=api;
})(globalThis);
